ClipboardPage myServicePage = tools.findPage("MyServicePage");
ClipboardPage claimDataPage = myServicePage.getPage("ClaimData");

String originalJson = claimDataPage.getString("NoteKasir");

// 1. Hapus semua field "pxObjClass"
String cleanedJson = originalJson.replaceAll(",?\\s*\"pxObjClass\"\\s*:\\s*\"[^\"]*\"", "");

// 2. Hapus koma sisa yang muncul sebelum objek atau array (akibat penghapusan pxObjClass)
cleanedJson = cleanedJson.replaceAll("\\{\\s*,", "{");
cleanedJson = cleanedJson.replaceAll("\\[\\s*,", "[");

// 3. Simpan kembali hasilnya
claimDataPage.putString("NoteKasir", cleanedJson);
